import React, { useEffect, useState } from "react";
import Navbar from "../components/Navbar";
import { api, API_BASE } from "../utils/api";

export default function Portal() {
  const [loading, setLoading] = useState(true);
  const [cases, setCases] = useState([]);

  async function loadMyCases() {
    const token = localStorage.getItem("user_token");
    if (!token) {
      window.location.href = "/login";
      return;
    }

    const res = await api.get("/api/portal/my-cases", {
      headers: { Authorization: `Bearer ${token}` }
    });

    setCases(res.data || []);
  }

  useEffect(() => {
    (async () => {
      setLoading(true);
      try {
        await loadMyCases();
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  function logout() {
    localStorage.removeItem("user_token");
    localStorage.removeItem("user_profile");
    window.location.href = "/";
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <Navbar />

      <div className="max-w-5xl mx-auto px-4 py-10">
        <div className="flex justify-between items-center gap-4">
          <div>
            <h1 className="text-4xl font-black">My Portal</h1>
            <p className="text-gray-600 mt-1">
              Track your scam reports and SOC reply.
            </p>
          </div>

          <button
            onClick={logout}
            className="px-6 py-3 rounded-2xl bg-gray-900 text-white font-semibold"
          >
            Logout
          </button>
        </div>

        {loading ? (
          <div className="mt-8 text-gray-600">Loading...</div>
        ) : (
          <div className="mt-8 space-y-4">
            {cases.map((c) => (
              <div
                key={c._id}
                className="bg-white rounded-3xl shadow p-6 border"
              >
                <div className="flex justify-between items-center gap-4">
                  <div className="font-black text-xl">{c.ticketId}</div>
                  <div className="text-xs font-bold">
                    {c.status} • {c.severity}
                  </div>
                </div>

                <div className="text-sm text-gray-600 mt-1">
                  {new Date(c.createdAt).toLocaleString()}
                </div>

                <div className="mt-4 text-sm">
                  <b>Your Message:</b>
                  <div className="mt-2 whitespace-pre-wrap text-gray-800">
                    {c.message}
                  </div>
                </div>

                {c.analystReply && (
                  <div className="mt-5 border rounded-2xl p-4 bg-gray-50">
                    <div className="font-black text-lg">SOC Reply</div>
                    <div className="mt-2 whitespace-pre-wrap text-gray-800">
                      {c.analystReply}
                    </div>
                  </div>
                )}

                {c.screenshotUrl && (
                  <div className="mt-5">
                    <div className="font-semibold text-sm">Screenshot</div>
                    <img
                      alt="screenshot"
                      className="mt-2 rounded-2xl border max-h-[260px]"
                      src={`${API_BASE}${c.screenshotUrl}`}
                    />
                  </div>
                )}
              </div>
            ))}

            {cases.length === 0 && (
              <div className="text-gray-600">No cases yet.</div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
